// Some portions generated by Codex
package org.eclipse.rdf4j.workbench.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import org.eclipse.rdf4j.workbench.base.WorkbenchViewRegistry;
import org.eclipse.rdf4j.workbench.commands.QueryServlet;
import org.eclipse.rdf4j.workbench.commands.SummaryServlet;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletResponse;

import jakarta.servlet.http.HttpServletRequest;

class WorkbenchPageProtocolTest {

	@Test
	void explicitResultFormatQueryParameterKeepsBrowserNavigationOutOfPageShell() {
		HttpServletRequest request = mock(HttpServletRequest.class);
		when(request.getHeader("Accept")).thenReturn("text/html,application/xhtml+xml");
		when(request.getParameterValues("Accept")).thenReturn(new String[] { "application/n-quads" });

		assertThat(WorkbenchPageProtocol.requestsHtmlNavigation(request)).isFalse();
	}

	@Test
	void explicitResultFormatQueryParameterKeepsStructuredRequestsAsRawFormats() {
		HttpServletRequest request = mock(HttpServletRequest.class);
		when(request.getHeader("Accept")).thenReturn(WorkbenchPageProtocol.ACCEPT);
		when(request.getParameterValues("Accept"))
				.thenReturn(new String[] { "application/sparql-results+json" });

		assertThat(WorkbenchPageProtocol.requestsPageData(request)).isFalse();
	}

	@Test
	void exportPreviewUsesTheWorkbenchPageProtocolDespiteItsSelectedDownloadFormat() {
		HttpServletRequest request = mock(HttpServletRequest.class);
		when(request.getMethod()).thenReturn("GET");
		when(request.getServletPath()).thenReturn("/repositories/test/export");
		when(request.getParameter("action")).thenReturn("preview");
		when(request.getParameterValues("Accept")).thenReturn(new String[] { "application/n-quads" });

		when(request.getHeader("Accept")).thenReturn("text/html,application/xhtml+xml");
		assertThat(WorkbenchPageProtocol.requestsHtmlNavigation(request)).isTrue();

		when(request.getHeader("Accept")).thenReturn(WorkbenchPageProtocol.ACCEPT);
		assertThat(WorkbenchPageProtocol.requestsPageData(request)).isTrue();

		when(request.getServletPath()).thenReturn("/repositories");
		when(request.getPathInfo()).thenReturn("/test/export");
		when(request.getHeader("Accept")).thenReturn("text/html,application/xhtml+xml");
		assertThat(WorkbenchPageProtocol.requestsHtmlNavigation(request)).isTrue();
	}

	@Test
	void exportDownloadAndNonExportPreviewKeepExplicitFormatsRaw() {
		HttpServletRequest request = mock(HttpServletRequest.class);
		when(request.getMethod()).thenReturn("GET");
		when(request.getParameterValues("Accept")).thenReturn(new String[] { "application/n-quads" });
		when(request.getServletPath()).thenReturn("/repositories/test/export");
		when(request.getParameter("action")).thenReturn("download");
		when(request.getHeader("Accept")).thenReturn("text/html,application/xhtml+xml");
		assertThat(WorkbenchPageProtocol.requestsHtmlNavigation(request)).isFalse();
		when(request.getHeader("Accept")).thenReturn(WorkbenchPageProtocol.ACCEPT);
		assertThat(WorkbenchPageProtocol.requestsPageData(request)).isFalse();

		when(request.getServletPath()).thenReturn("/repositories/test/summary");
		when(request.getParameter("action")).thenReturn("preview");
		when(request.getHeader("Accept")).thenReturn("text/html,application/xhtml+xml");
		assertThat(WorkbenchPageProtocol.requestsHtmlNavigation(request)).isFalse();
		when(request.getHeader("Accept")).thenReturn(WorkbenchPageProtocol.ACCEPT);
		assertThat(WorkbenchPageProtocol.requestsPageData(request)).isFalse();
	}

	@Test
	void queryExecutionRequestDoesNotEmitGenericPageViewBeforeResultHeartbeat() {
		HttpServletRequest request = mock(HttpServletRequest.class);
		when(request.getParameter("action")).thenReturn(null);
		when(request.getParameterValues("query")).thenReturn(new String[] { "SELECT * WHERE { ?s ?p ?o }" });

		assertThat(WorkbenchViewRegistry.pageRequestViewId(QueryServlet.class, request)).isEmpty();
	}

	@Test
	void customServletSubclassInheritsItsStablePageView() {
		assertThat(WorkbenchViewRegistry.viewId(CustomSummaryServlet.class)).contains("summary");
		assertThat(WorkbenchViewRegistry.navigableViewId(CustomSummaryServlet.class)).contains("summary");
		assertThat(WorkbenchViewRegistry.pageRequestViewId(CustomSummaryServlet.class,
				mock(HttpServletRequest.class))).contains("summary");
	}

	@Test
	void dynamicPageHeadersDisableCachingAndMergeAcceptIntoExistingVary() {
		MockHttpServletResponse response = new MockHttpServletResponse();
		response.addHeader("Vary", "Cookie, Accept-Language");

		WorkbenchPageProtocol.configureDynamicPageResponse(response);
		WorkbenchPageProtocol.configureDynamicPageResponse(response);

		assertThat(response.getHeader("Cache-Control")).isEqualTo("no-cache, no-store");
		assertThat(response.getHeaders("Vary")).containsExactly("Cookie, Accept-Language", "Accept");
	}

	private static final class CustomSummaryServlet extends SummaryServlet {
	}
}
